package com.dorm.platform;

import com.dorm.platform.common.*;
import com.dorm.platform.security.*;
import com.dorm.platform.repair.service.RepairService;
import com.dorm.platform.stay.service.StayService;
import com.dorm.platform.system.service.ManagementService;
import com.dorm.platform.file.service.FileService;
import com.dorm.platform.notice.service.NoticeService;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.transaction.annotation.Transactional;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest(properties={
 "spring.datasource.url=jdbc:mysql://localhost:3306/dorm_platform_test?useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai&allowPublicKeyRetrieval=true&useSSL=false",
 "workflow.delay-ms=3600000", "system-task.delay-ms=3600000", "backup.database=dorm_platform_test"})
@AutoConfigureMockMvc @Transactional
class WorkflowIntegrationTest {
 @Autowired RepairService repair; @Autowired StayService stay; @Autowired ManagementService management;
 @Autowired FileService files; @Autowired NoticeService notice; @Autowired SqlStore db;
 @Autowired MockMvc mvc; @Autowired ObjectMapper json;
 @Autowired com.dorm.platform.system.service.SystemTaskService tasks;
 final CurrentUser student=new CurrentUser(1,"student1","Student","STUDENT");
 final CurrentUser manager=new CurrentUser(2,"manager1","Manager","DORM_MANAGER");
 final CurrentUser worker=new CurrentUser(3,"repair1","Worker","REPAIRER");
 final CurrentUser admin=new CurrentUser(4,"admin","Admin","ADMIN");
 @Test void exportTaskCanRunAndPendingTaskCanCancel(){long task=Input.id(tasks.create(admin,Map.of("taskType","EXPORT","businessType","users")).get("taskId"));assertEquals("WAITING",tasks.dataTask(admin,task).get("task_status"));tasks.runWaiting();assertEquals("SUCCESS",tasks.dataTask(admin,task).get("task_status"));assertEquals(1L,db.count("SELECT COUNT(*) FROM import_export_task_file WHERE task_id=? AND file_purpose='OUTPUT'",task));assertThrows(BizException.class,()->tasks.cancel(admin,task));long pending=Input.id(tasks.create(admin,Map.of("taskType","EXPORT","businessType","users")).get("taskId"));tasks.cancel(admin,pending);assertEquals("CANCELLED",tasks.dataTask(admin,pending).get("task_status"));assertEquals(403,assertThrows(BizException.class,()->tasks.dataTask(student,task)).status());}
 Map<String,Object> body(){return new HashMap<>(Map.of("title","Integration repair","description","Socket broken","categoryId",2));}
 @Test void unassignedStudentCanReadEmptyAccommodation(){long id=management.saveUser(admin,null,Map.of("account","unassigned-"+UUID.randomUUID(),"realName","New","roleCode","STUDENT","password","123456"));var user=new CurrentUser(id,"new","New","STUDENT");assertTrue(management.homes(user,false).isEmpty());assertTrue(management.roommates(user).isEmpty());assertTrue(management.roommates(student).stream().noneMatch(x->"A".equals(x.get("bed_no"))));}
 @Test void stayDashboardCountsPeopleNotApplications()throws Exception{var controller=new com.dorm.platform.system.controller.ManagementController(management,repair,stay,notice,files);long before=((Number)((Map<?,?>)controller.dashboard(manager).data()).get("stayApproved")).longValue();boolean alreadyApproved=stay.list(manager).stream().anyMatch(x->Input.id(x.get("student_user_id"))==1&&"APPROVED".equals(x.get("current_status")));for(int i=0;i<2;i++){long b=batch();publish(b);long a=application(b);stay.submit(student,a);stay.lock(manager,a,true);stay.review(manager,a,Map.of("pass",true));}long after=((Number)((Map<?,?>)controller.dashboard(manager).data()).get("stayApproved")).longValue();assertEquals(before+(alreadyApproved?0:1),after);}
 long create(){long id=Input.id(repair.create(student,body()).get("orderId"));repair.submit(student,id);return id;}
 Map<String,Object> order(long id){return repair.detail(student,id);}
 String state(long id){return order(id).get("current_status").toString();}
 long photo(CurrentUser user)throws Exception{byte[] png=Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=");return Input.id(files.upload(user,new MockMultipartFile("file","evidence.png","image/png",png)).get("fileId"));}
 long accepted(){long id=create();repair.review(manager,id,Map.of("pass",true));assertEquals("PENDING_ACCEPT",state(id));repair.decision(worker,id,Map.of("accept",true));return id;}
 void complete(long id)throws Exception{repair.result(worker,id,Map.of("result","Repaired and tested","fileIds",List.of(photo(worker))));}
 long batch(){return Input.id(stay.configure(admin,null,Map.of("batchCode",UUID.randomUUID().toString(),"batchName","Test holiday","openStartDate",LocalDate.now().plusDays(1).toString(),"openEndDate",LocalDate.now().plusDays(30).toString(),"instructions","Test")).get("batchId"));}
 void publish(long b){stay.publish(manager,b,Map.of("buildingId",1,"applicationDeadline",LocalDateTime.now().plusHours(1).toString(),"autoLock",true));}
 Map<String,Object> stayBody(long b){return Map.of("batchId",b,"reason","Study","dateRanges",List.of(Map.of("startDate",LocalDate.now().plusDays(2).toString(),"endDate",LocalDate.now().plusDays(4).toString()),Map.of("startDate",LocalDate.now().plusDays(6).toString(),"endDate",LocalDate.now().plusDays(8).toString())));}
 long application(long b){return Input.id(stay.save(student,stayBody(b)).get("applicationId"));}
 String stayState(long a){return db.one("SELECT current_status FROM stay_application WHERE application_id=?",a).get("current_status").toString();}
 @Test void repairCompletesAcrossRoles()throws Exception{long id=accepted();assertThrows(BizException.class,()->repair.result(worker,id,Map.of("result","Missing photos")));complete(id);repair.confirm(student,id);repair.evaluate(student,id,Map.of("score",5,"comment","Good"));assertEquals("ARCHIVED",state(id));assertEquals(5,((Number)order(id).get("score")).intValue());assertTrue(notice.list(student).size()>0);}
 @Test void withdrawnStayCanSubmitAgain(){long b=batch();publish(b);long a=application(b);stay.submit(student,a);stay.withdraw(student,a);stay.submit(student,a);assertEquals("PENDING_REVIEW",stayState(a));}
 @Test void supplementAndRangeChangesAreReviewed(){long b=batch();publish(b);db.update("UPDATE stay_building_rule SET application_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE batch_id=?",b);var payload=new HashMap<>(stayBody(b));payload.put("studentUserId",1);long a=Input.id(stay.supplement(manager,payload).get("applicationId"));assertEquals("LATE",db.one("SELECT source FROM stay_application WHERE application_id=?",a).get("source"));stay.review(admin,a,Map.of("pass",true));stay.configure(admin,b,Map.of("batchName","Changed","openStartDate",LocalDate.now().plusDays(10).toString(),"openEndDate",LocalDate.now().plusDays(30).toString(),"instructions","Changed"));assertEquals("UNDER_REVIEW",stayState(a));assertThrows(BizException.class,()->stay.review(manager,a,Map.of("pass",true)));stay.review(manager,a,Map.of("pass",false,"reason","Outside new range","resubmitDeadline",LocalDateTime.now().plusHours(2).toString()));assertEquals("PENDING_EDIT",stayState(a));}
 @Test void maintenanceScopeWorkloadAndReworkCap(){management.worker(admin,3,Map.of("onDuty",true,"maxActiveOrders",1,"workTypeIds",List.of(1),"buildingIds",List.of(1)));long id=create();repair.review(manager,id,Map.of("pass",true));assertEquals("PENDING_MANUAL",state(id));assertThrows(BizException.class,()->repair.dispatch(manager,id,Map.of("repairerUserId",3)));management.worker(admin,3,Map.of("onDuty",true,"maxActiveOrders",1,"workTypeIds",List.of(2),"buildingIds",List.of(1)));repair.retry(manager,id);assertEquals("PENDING_MANUAL",state(id));repair.dispatch(manager,id,Map.of("repairerUserId",3));assertEquals("ACCEPTED",state(id));}
 @Test void repairReturnEditAndReworkCap()throws Exception{management.saveRule(admin,Map.of("accept_minutes",120,"normal_minutes",1440,"urgent_minutes",360,"confirm_days",7,"edit_days",7,"max_rework_count",0));long id=create();repair.review(manager,id,Map.of("pass",false,"reason","Clarify"));var b=body();b.put("description","Updated details");repair.edit(student,id,b);repair.submit(student,id);repair.review(manager,id,Map.of("pass",true));repair.decision(worker,id,Map.of("accept",true));complete(id);assertThrows(BizException.class,()->repair.rework(student,id,Map.of("reason","Still broken")));assertEquals(2L,db.count("SELECT COUNT(*) FROM repair_submission_version WHERE order_id=?",id));}
 @Test void foreignStayCannotBeReviewed(){long b=batch();publish(b);long a=application(b);stay.submit(student,a);long mgr=management.saveUser(admin,null,Map.of("account","isolated","realName","Isolated","roleCode","DORM_MANAGER","password","123456","buildingIds",List.of(2)));var other=new CurrentUser(mgr,"isolated","Isolated","DORM_MANAGER");assertTrue(stay.list(other).isEmpty());assertEquals(403,assertThrows(BizException.class,()->stay.lock(other,a,true)).status());}
 @Test void delayedNoticesAreDeliveredOnce(){long before=db.count("SELECT COUNT(*) FROM message_receipt");long students=db.count("SELECT COUNT(*) FROM sys_user WHERE role_code='STUDENT' AND enabled=1");notice.publish(admin,Map.of("title","Scheduled","content","Notification","targetRole","STUDENT","publishAt",LocalDateTime.now().plusHours(1).toString()));assertEquals(before,db.count("SELECT COUNT(*) FROM message_receipt"));long message=db.count("SELECT MAX(message_id) FROM site_message");db.update("UPDATE site_message SET publish_at=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE message_id=?",message);notice.deliver();notice.deliver();assertEquals(before+students,db.count("SELECT COUNT(*) FROM message_receipt"));}
 @Test void immediateNoticeIsVisibleBeforeSchedulerRuns(){long before=db.count("SELECT COUNT(*) FROM message_receipt WHERE user_id=1");notice.publish(admin,Map.of("title","Immediate","content","Visible now","targetRole","STUDENT"));assertEquals(before+1,db.count("SELECT COUNT(*) FROM message_receipt WHERE user_id=1"));}
 @Test void disabledAccountsLoseActiveSessions()throws Exception{String response=mvc.perform(post("/api/v1/auth/login").contentType("application/json").content("{\"loginAccount\":\"student1\",\"password\":\"123456\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String token=json.readTree(response).path("data").path("token").asText();management.enabled(admin,1,false);mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+token)).andExpect(status().isUnauthorized());}
 @Test void urgentManualDispatchCannotBeRejected(){long id=create();repair.review(manager,id,Map.of("pass",true,"urgent",true));assertEquals("PENDING_MANUAL",state(id));repair.dispatch(manager,id,Map.of("repairerUserId",3));assertEquals("ACCEPTED",state(id));assertThrows(BizException.class,()->repair.decision(worker,id,Map.of("accept",false,"reason","No")));}
 @Test void rejectionWithoutNewCandidateStopsAutoDispatch(){long id=create();repair.review(manager,id,Map.of("pass",true));assertThrows(BizException.class,()->repair.decision(worker,id,Map.of("accept",false)));repair.decision(worker,id,Map.of("accept",false,"reason","Unavailable"));assertEquals("PENDING_MANUAL",state(id));assertEquals(1L,Input.id(order(id).get("reject_count")));assertTrue(repair.list(worker).stream().anyMatch(x->Input.id(x.get("order_id"))==id));}
 @Test void threeRefusalsMarkAbnormal(){for(int i=0;i<2;i++){long uid=management.saveUser(admin,null,Map.of("account","testworker"+i,"password","123456","realName","Worker","roleCode","REPAIRER"));management.worker(admin,uid,Map.of("onDuty",true,"workTypeIds",List.of(2),"buildingIds",List.of(1)));}long id=create();repair.review(manager,id,Map.of("pass",true));for(int i=0;i<3;i++){long uid=Input.id(order(id).get("repairer_user_id"));repair.decision(new CurrentUser(uid,"test","test","REPAIRER"),id,Map.of("accept",false,"reason","Unavailable"));}assertEquals("PENDING_MANUAL",state(id));assertEquals(3L,Input.id(order(id).get("reject_count")));assertTrue(Input.flag(order(id),"abnormal"));assertThrows(BizException.class,()->repair.retry(manager,id));}
 @Test void delayApprovalAndRejectionKeepCorrectDeadlines()throws Exception{long id=accepted();String original=order(id).get("repair_deadline").toString();repair.delay(worker,id,Map.of("reason","Need parts","expectedFinishAt",LocalDateTime.now().plusDays(3).toString(),"fileIds",List.of(photo(worker))));assertEquals("DELAYED",state(id));repair.reviewDelay(manager,id,Map.of("pass",false,"reason","Use available parts"));assertEquals("ACCEPTED",state(id));assertEquals(original,order(id).get("repair_deadline").toString());repair.delay(worker,id,Map.of("reason","Need parts","expectedFinishAt",LocalDateTime.now().plusDays(3).toString(),"fileIds",List.of(photo(worker))));repair.reviewDelay(manager,id,Map.of("pass",true));assertTrue(Input.time(order(id).get("repair_deadline")).isAfter(LocalDateTime.now().plusDays(2)));complete(id);}
 @Test void pendingDelayPausesTimeoutAndRejectedExpiredDelayReassigns()throws Exception{long id=accepted();repair.delay(worker,id,Map.of("reason","Parts","expectedFinishAt",LocalDateTime.now().plusDays(3).toString(),"fileIds",List.of(photo(worker))));db.update("UPDATE repair_dispatch SET repair_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE order_id=?",id);repair.tick();assertEquals("DELAYED",state(id));repair.reviewDelay(manager,id,Map.of("pass",false,"reason","Not approved"));assertEquals("PENDING_MANUAL",state(id));assertNull(order(id).get("repairer_user_id"));assertEquals(1L,Input.id(order(id).get("repair_timeout_count")));}
 @Test void reworkUsesManualAssignmentAndArchivesParent()throws Exception{long id=accepted();complete(id);long child=Input.id(repair.rework(student,id,Map.of("reason","Still broken")).get("orderId"));assertThrows(BizException.class,()->repair.confirm(student,id));repair.review(manager,child,Map.of("pass",true));assertEquals("PENDING_MANUAL",state(child));repair.dispatch(manager,child,Map.of("repairerUserId",3));complete(child);repair.confirm(student,child);assertEquals("ARCHIVED",state(id));}
 @Test void timersAreIdempotent()throws Exception{long waiting=create();repair.review(manager,waiting,Map.of("pass",true));db.update("UPDATE repair_dispatch SET accept_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE order_id=?",waiting);long repaired=accepted();complete(repaired);db.update("UPDATE repair_result SET created_at=DATE_SUB(NOW(),INTERVAL 8 DAY) WHERE order_id=?",repaired);long edit=create();repair.review(manager,edit,Map.of("pass",false,"reason","Clarify"));db.update("UPDATE repair_audit SET created_at=DATE_SUB(NOW(),INTERVAL 8 DAY) WHERE order_id=?",edit);repair.tick();repair.tick();assertEquals(1L,Input.id(order(waiting).get("accept_timeout_count")));assertEquals("ARCHIVED",state(repaired));assertEquals("CLOSED",state(edit));assertEquals(1L,db.count("SELECT COUNT(*) FROM repair_confirmation WHERE order_id=?",repaired));}
 @Test void stayLocksResubmitsAndArchives(){long b=batch();publish(b);long a=application(b);assertFalse(stay.list(manager).stream().anyMatch(x->Input.id(x.get("application_id"))==a));stay.submit(student,a);assertThrows(BizException.class,()->stay.review(manager,a,Map.of("pass",true)));stay.lock(manager,a,true);assertThrows(BizException.class,()->stay.save(student,stayBody(b)));stay.review(manager,a,Map.of("pass",false,"reason","Need details","resubmitDeadline",LocalDateTime.now().plusHours(2).toString()));application(b);assertEquals("PENDING_EDIT",stayState(a));stay.submit(student,a);assertEquals("UNDER_REVIEW",stayState(a));assertThrows(BizException.class,()->stay.review(manager,a,Map.of("pass",true)));db.update("UPDATE stay_application SET resubmit_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE application_id=?",a);stay.review(manager,a,Map.of("pass",true));db.update("UPDATE stay_date_range d JOIN stay_version v ON v.version_id=d.version_id SET d.start_date=DATE_SUB(CURRENT_DATE(),INTERVAL 2 DAY),d.end_date=DATE_SUB(CURRENT_DATE(),INTERVAL 1 DAY) WHERE v.application_id=?",a);stay.tick();assertEquals("COMPLETED",stayState(a));}
 @Test void staySharedBoundaryIsOverlap(){LocalDate d=LocalDate.now();assertThrows(BizException.class,()->StayService.validateRanges(List.of(Map.of("startDate",d.toString(),"endDate",d.plusDays(2).toString()),Map.of("startDate",d.plusDays(2).toString(),"endDate",d.plusDays(3).toString())),d,d.plusDays(5)));}
 @Test void unsubmittedEditsAreNotReviewed(){long b=batch();publish(b);long a=application(b);stay.submit(student,a);var edit=new HashMap<>(stayBody(b));edit.put("reason","Unsubmitted draft");stay.save(student,edit);assertEquals("Study",stay.list(manager).stream().filter(x->Input.id(x.get("application_id"))==a).findFirst().orElseThrow().get("reason"));stay.lock(manager,a,true);stay.review(manager,a,Map.of("pass",true));assertEquals("Study",stay.list(student).stream().filter(x->Input.id(x.get("application_id"))==a).findFirst().orElseThrow().get("reason"));}
 @Test void stayAutomaticLockAndExpiredReturn(){long b=batch();publish(b);long a=application(b);stay.submit(student,a);db.update("UPDATE stay_building_rule SET application_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE batch_id=?",b);stay.tick();assertEquals("UNDER_REVIEW",stayState(a));assertThrows(BizException.class,()->stay.lock(manager,a,false));stay.review(manager,a,Map.of("pass",false,"reason","Incomplete","resubmitDeadline",LocalDateTime.now().plusHours(1).toString()));db.update("UPDATE stay_application SET resubmit_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE application_id=?",a);stay.tick();assertEquals("ARCHIVED",stayState(a));assertEquals("未按期重新提交",db.one("SELECT archive_reason FROM stay_application WHERE application_id=?",a).get("archive_reason"));}
 @Test void studentAndBuildingIsolation(){long id=create();long other=management.saveUser(admin,null,Map.of("account","other","realName","Other","roleCode","STUDENT","password","123456"));var user=new CurrentUser(other,"other","Other","STUDENT");assertEquals(403,assertThrows(BizException.class,()->repair.detail(user,id)).status());long mgr=management.saveUser(admin,null,Map.of("account","othermanager","realName","Other","roleCode","DORM_MANAGER","password","123456","buildingIds",List.of(2)));var m=new CurrentUser(mgr,"othermanager","Other","DORM_MANAGER");assertTrue(repair.list(m).isEmpty());assertEquals(403,assertThrows(BizException.class,()->repair.review(m,id,Map.of("pass",true))).status());assertEquals(403,assertThrows(BizException.class,()->files.get(user,photo(student))).status());}
 @Test void loginLogoutAndHttpStatus()throws Exception{String login=mvc.perform(post("/api/v1/auth/login").contentType("application/json").content("{\"loginAccount\":\"student1\",\"password\":\"123456\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String token=json.readTree(login).path("data").path("token").asText();mvc.perform(get("/api/v1/admin/users").header("Authorization","Bearer "+token)).andExpect(status().isForbidden());mvc.perform(post("/api/v1/auth/logout").header("Authorization","Bearer "+token)).andExpect(status().isOk());mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+token)).andExpect(status().isUnauthorized());mvc.perform(post("/api/v1/auth/login").contentType("application/json").content("{}")).andExpect(status().isBadRequest());}
 @Test void occupiedBedAndUnauthorizedMessageAreRejected(){long other=management.saveUser(admin,null,Map.of("account","newstudent","realName","New","roleCode","STUDENT","password","123456"));assertThrows(BizException.class,()->management.assign(admin,Map.of("studentUserId",other,"bedId",1)));notice.send(List.of(3L),"Private","Repair only");long id=db.count("SELECT MAX(message_id) FROM site_message");assertEquals(403,assertThrows(BizException.class,()->notice.read(student,id)).status());}
}
